namespace QuantForge.Core;public sealed record AndroidNativeTestHandoff(string AppVersion,string BuildCode,string Commit,string Tree,string ExpectedArtifactName,IReadOnlyList<string> RequiredScenarios,bool ProductionSigningRequired);public static class AndroidNativeTestHandoffRules{public static AndroidNativeTestHandoff Create(string appVersion,string buildCode,string commit,string tree,string expectedArtifactName,IEnumerable<string> scenarios){if(new[]{appVersion,buildCode,commit,tree,expectedArtifactName}.Any(string.IsNullOrWhiteSpace))throw new InvalidOperationException("Android test handoff identity is incomplete.");var a=scenarios.Where(x=>!string.IsNullOrWhiteSpace(x)).Distinct(StringComparer.Ordinal).OrderBy(x=>x,StringComparer.Ordinal).ToArray();if(a.Length==0)throw new InvalidOperationException("Android test handoff requires at least one scenario.");return new(appVersion,buildCode,commit,tree,expectedArtifactName,a,false);}}
